---@field clipboard { osc52_read: ("ask"|"allow"|"deny")?, osc52_write: boolean?, paste_protection: boolean? }?
---@field shell { command: (string|string[])?, integration: boolean? }?
---@field scrollback integer?
---@field ui { hint_bar: ("in-mode"|"always"|"never")?, tab_bar: ("auto"|"always"|"never")?, pane_titles: ("auto"|"always"|"never")?, gutter: number? }?
---@field panes { confirm_close: boolean?, confirm_close_ignore: string[]?, keep_last_shell: boolean? }?
---@field session { restore: ("ask"|"always"|"never")?, restore_commands: string[]? }?
---@field notify { min_duration: (number|false)?, osc: boolean? }?
---@field bell { visual: boolean? }?
---@field graphics { enabled: boolean?, max_image: number?, pane_memory: number?, total_memory: number?, gpu_memory: number?, local_files: boolean? }?
---@field hints { alphabet: string?, patterns: { name: string?, regex: string, url: string? }[]? }?
---@field keys table? preset, leader, sticky, and per-mode tables of key = action name.

---@alias proteus.Mode "normal"|"locked"|"menu"|"pane"|"tab"|"resize"|"move"|"scroll"|"session"

---@class proteus
---@field version string
local p = {}

---Set options; later calls override earlier keys. Only while the config loads.
---@param cfg proteus.Config
function p.config(cfg) end

---Bind a key in a mode to an action name (`proteus --list-actions`), a
---function, or "none"/false to unbind. Only while the config loads.
---@param mode proteus.Mode
---@param key string e.g. "alt+g", "ctrl+shift+k", "f5"
---@param action string|false|fun(ctx: proteus.Ctx)
function p.keymap(mode, key, action) end

---Run `f` on an event.
---@param event proteus.Event
---@param f fun(ev: proteus.EventData)
function p.on(event, f) end

---Run an action by name on the focused pane.
---@param name string
function p.run_action(name) end

---A message in the window (top right).
---@param text string
---@param opts { level: ("info"|"error")?, timeout: number? }?
function p.notify(text, opts) end

---Run `f` once after `secs` seconds.
---@param secs number
---@param f fun()
---@return proteus.Timer
function p.after(secs, f) end

---Run `f` every `secs` seconds until stopped.
---@param secs number
---@param f fun()
---@return proteus.Timer
function p.every(secs, f) end

p.panes = {}
---@return proteus.Pane[]
function p.panes.list() end
---@return proteus.Pane?
function p.panes.focused() end
---@param id integer
---@return proteus.Pane?
function p.panes.get(id) end
---@param opts proteus.SpawnOpts?
---@return proteus.Pane
function p.panes.new_tab(opts) end
---@param opts proteus.SpawnOpts?
---@return proteus.Pane
function p.panes.float(opts) end

p.status = {}
---A tab-bar segment; `f` returns its text (nil or "" hides it). It runs
---after events and once a second, so keep it fast.
---@param side "left"|"right"
---@param f fun(ctx: proteus.Ctx): string?
function p.status.segment(side, f) end

p.palette = {}
---A command palette entry (Ctrl+Shift+P); the same name replaces it.
---@param name string
---@param f fun(ctx: proteus.Ctx)
function p.palette.add(name, f) end

return p
